mod solution;

fn main() {
    let cases = [
    (r#"[1,3] and [2,4]"#, r#"2.5"#),
    (r#"[1] and [3]"#, r#"2"#),
    (r#"
[1] and [3]
"#, r#"2"#),
    (r#"  
[1,3] and [2,4]
  "#, r#"2.5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS partition-median");
}
